package com.meridian.payments.intake;
import org.junit.jupiter.api.*; import java.nio.charset.*; import java.nio.file.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class WebhookIntakeServiceTest {
 static final String QS="qz_test_whsec_4f8a1c2e9b7d", AS="andina_test_secret_7c3e19ab";
 MemoryInbox inbox; List<CanonicalPaymentEvent> events; WebhookIntakeService service;
 @BeforeEach void setup(){inbox=new MemoryInbox();events=new ArrayList<>();service=new WebhookIntakeService(inbox,events::add,Clock.fixed(Instant.parse("2026-11-28T19:03:11Z"),ZoneOffset.UTC));}
 @Test void quetzalVectorMapsMinorUnits()throws Exception{service=new WebhookIntakeService(inbox,events::add,Clock.fixed(Instant.parse("2026-11-28T18:00:03Z"),ZoneOffset.UTC));var r=service.quetzal(sample("reference/providers/quetzal-mx/samples/01-charge-succeeded.json"),"t=1795888803,v1=2d07770582c02f15235ac4e027b7732beef86be103c574a1c3b988a4275f5031",QS,UUID.randomUUID());assertTrue(r.accepted(),r.code());assertEquals("1250.00",events.getFirst().amount().toPlainString());assertEquals("POL-MX-000412785",events.getFirst().policyNumber());}
 @Test void andinaApprovalVectorMapsCanonical()throws Exception{var r=service.andina(sample("reference/providers/andina-co/samples/02-transaccion-aprobada.json"),"2026-11-28T14:03:11-05:00","MFQjfviySi6CjqbWtQcy5spKtXxHIxAvmg5W3PTzPJk=",AS,UUID.randomUUID());assertTrue(r.accepted(),r.code());assertEquals("Captured",events.getFirst().status());assertEquals("185000.00",events.getFirst().amount().toPlainString());}
 @Test void andinaRetryWithNewAttemptIdDedupesBusinessTransition()throws Exception{service.andina(sample("reference/providers/andina-co/samples/02-transaccion-aprobada.json"),"2026-11-28T14:03:11-05:00","MFQjfviySi6CjqbWtQcy5spKtXxHIxAvmg5W3PTzPJk=",AS,UUID.randomUUID());var r=service.andina(sample("reference/providers/andina-co/samples/03-transaccion-aprobada-reintento.json"),"2026-11-28T14:08:11-05:00","CNu6m5X6B9bMKTsi/IzZfGquIh/KdxTyesBtL4ax424=",AS,UUID.randomUUID());assertEquals("duplicate",r.code());assertEquals(1,events.size());}
 @Test void invalidSignatureDoesNotPersist()throws Exception{var r=service.andina(sample("reference/providers/andina-co/samples/02-transaccion-aprobada.json"),"2026-11-28T14:03:11-05:00","AAAA",AS,UUID.randomUUID());assertEquals(401,r.httpStatus());assertTrue(inbox.keys.isEmpty());}
 @Test void malformedPolicyIsRejectedNotGuessed()throws Exception{byte[] b=sample("reference/providers/andina-co/samples/02-transaccion-aprobada.json");String t="2026-11-28T14:03:11-05:00";byte[] raw=new String(b,UTF_8).replace("POL-CO-000187342","000187342").getBytes(UTF_8);String sig=Base64.getEncoder().encodeToString(sign(AS,(t+".").getBytes(UTF_8),raw));var r=service.andina(raw,t,sig,AS,UUID.randomUUID());assertEquals("invalid_policy_reference",r.code());}
 private static final Charset UTF_8=StandardCharsets.UTF_8;
 private static byte[] sample(String p)throws Exception{String s=Files.readString(Path.of("..",p),UTF_8).replace("\r\n","\n").replace("\r","\n");while(s.endsWith("\n"))s=s.substring(0,s.length()-1);return s.getBytes(UTF_8);}
 private static byte[] sign(String s,byte[] prefix,byte[] body)throws Exception{var m=javax.crypto.Mac.getInstance("HmacSHA256");m.init(new javax.crypto.spec.SecretKeySpec(s.getBytes(UTF_8),"HmacSHA256"));m.update(prefix);return m.doFinal(body);}
 static class MemoryInbox implements Inbox{Set<String> keys=new HashSet<>();public boolean accept(String k,byte[] b,String p,String c,Instant i){return keys.add(k);}}
}